import{c as t,Q as a,j as l,m as s}from"./chunks/framework.DOi4mjdC.js";const n="/assets/Block%E5%92%8C%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%97%E6%98%A0%E5%B0%84%E7%A4%BA%E6%84%8F%E5%9B%BE.CJxj4xbB.png",h=JSON.parse('{"title":"CubeResGroupHandle构造函数","description":"","frontmatter":{},"headers":[{"level":1,"title":"CubeResGroupHandle构造函数","slug":"cuberesgrouphandle构造函数"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Cube分组管理（ISASI）/CubeResGroupHandle/CubeResGroupHandle构造函数.md","filePath":"api/SIMD-API/基础API/Cube分组管理（ISASI）/CubeResGroupHandle/CubeResGroupHandle构造函数.md"}'),d={name:"api/SIMD-API/基础API/Cube分组管理（ISASI）/CubeResGroupHandle/CubeResGroupHandle构造函数.md"};function r(o,e,u,i,p,c){return a(),l("div",null,[...e[0]||(e[0]=[s(`<h1 id="cuberesgrouphandle构造函数" tabindex="-1">CubeResGroupHandle构造函数 <a class="header-anchor" href="#cuberesgrouphandle构造函数" aria-label="Permalink to &quot;CubeResGroupHandle构造函数&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>构造CubeResGroupHandle对象，完成组内的AIC和消息队列分配。构造CubeResGroupHandle对象时需要传入模板参数CubeMsgType，CubeMsgType是由用户定义的消息结构体，请参考<a href="./CubeResGroupHandle使用说明.html#table189051237164018">表1</a>。使用此接口需要用户自主管理地址、同步事件等，因此更推荐使用<a href="./CubeResGroupHandle构造函数.html">CreateCubeResGroup</a>接口快速创建CubeResGroupHandle对象。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename CubeMsgType&gt;</span></span>
<span class="line"><span>class CubeResGroupHandle;</span></span>
<span class="line"><span>__aicore__ inline CubeResGroupHandle() = default</span></span>
<span class="line"><span>__aicore__ inline CubeResGroupHandle(GM_ADDR workspace, uint8_t blockStart, uint8_t blockSize, uint8_t msgQueueSize, uint8_t evtIDIn)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> CubeResGroupHandle参数说明</p><table tabindex="0"><thead><tr><th>参数</th><th>输入/输出</th><th>说明</th></tr></thead><tbody><tr><td>workspace</td><td>输入</td><td>该CubeResGroupHandle的消息通讯区在GM上的起始地址。</td></tr><tr><td>blockStart</td><td>输入</td><td>该CubeResGroupHandle在AIV视角下起始AIC对应的序号，即AIC的起始序号<em>2。例如，如果AIC起始序号为0，则填入0</em>2；如果为1，则填入1*2。</td></tr><tr><td>blockSize</td><td>输入</td><td>该CubeResGroupHandle在AIV视角下分配的Block个数，即实际的AIC个数*2。</td></tr><tr><td>msgQueueSize</td><td>输入</td><td>该CubeResGroupHandle分配的消息队列总数。</td></tr><tr><td>evtIDIn</td><td>输入</td><td>通信框架内用于AIV侧消息的同步事件。</td></tr></tbody></table><p>如下图所示，CubeResGroupHandle1的blockStart为4，blockSize为4，表示起始的AIC序号为2，即blockStart / 2；AIC数量为2，即blockSize / 2。msgQueueSize为10，表示消息队列个数为10，每个Block分配的消息队列个数为Ceil(msgQueueSize，blockSize/2)，Block2和Block3分配到的消息队列个数均为5。CubeResGroupHandle2的msgQueueSize数量为11，最后一个Block只能分配5个消息队列。</p><p><strong>图 1</strong> Block和消息队列映射示意图<br><img src="`+n+`" alt="" title="Block和消息队列映射示意图"></p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>假设芯片的AIV核数为x，那么blockStart + blockSize &lt;= x - 1, msgQueueSize &lt;= x。</li><li>每个AIC至少被分配1个消息队列msgQueue。</li><li>blockStart和blockSize必须为偶数。</li><li>使用该接口，UB空间末尾的1600B + sizeof(CubeMsgType)将被占用。</li><li>1个AIC只能属于1个CubeGroupHandle，即多个CubeGroupHandle的[blockStart / 2, blockStart / 2+blockSize / 2]区间不能重叠。</li><li>不能和<a href="./../../../高阶API/矩阵计算/Matmul-Kernel侧接口/REGIST_MATMUL_OBJ.html">REGIST_MATMUL_OBJ</a>接口同时使用。使用资源管理API时，用户自主管理AIC和AIV的核间通信，REGIST_MATMUL_OBJ内部是由框架管理AIC和AIV的核间通信，同时使用可能会导致通信消息错误等异常。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint8_t blockStart = 4;</span></span>
<span class="line"><span>uint8_t blockSize = 4;</span></span>
<span class="line"><span>uint8_t msgQueueSize = 10;</span></span>
<span class="line"><span>uint8_t evtIDIn = 0; //用户自行管理事件ID</span></span>
<span class="line"><span>AscendC::KfcWorkspace desc(workspace); // 用户自行管理的workspace指针。</span></span>
<span class="line"><span>AscendC::CubeResGroupHandle&lt;CubeMsgBody&gt; handle;</span></span>
<span class="line"><span>handle = AscendC::CubeResGroupHandle&lt;MatmulApiType, MyCallbackFunc, CubeMsgBody&gt;(desc.GetMsgStart(), blockStart, blockSize, msgQueueSize, evtIDIn);</span></span></code></pre></div>`,16)])])}const C=t(d,[["render",r]]);export{h as __pageData,C as default};
